// Builds src/data/hx-catalog.gen.ts from the toneharness HX Edit catalog.
//
// Source: https://github.com/retr0h/toneharness (MIT), pkg/sdk/catalog/data/helix-floor.json.gz,
// generated by that project from HX Edit 3.82's own model database. Stomp, Stomp XL, Floor and LT
// share every model and parameter; Floor adds FX Loop/Send/Return 3–4.
//
//   node scripts/build-hx-catalog.mjs /path/to/helix-floor.json.gz
import { readFileSync, writeFileSync } from "node:fs";
import { gunzipSync } from "node:zlib";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const src = process.argv[2];
if (!src) {
  console.error("usage: node scripts/build-hx-catalog.mjs helix-floor.json[.gz]");
  process.exit(2);
}
const raw = readFileSync(src);
const catalog = JSON.parse((src.endsWith(".gz") ? gunzipSync(raw) : raw).toString("utf8"));
const TYPE = { float: "f", int: "i", bool: "b" };

const models = {};
for (const [id, m] of Object.entries(catalog.blocks).sort(([a], [b]) => a.localeCompare(b))) {
  const params = {};
  for (const [key, p] of Object.entries(m.params ?? {}).sort(([a], [b]) => a.localeCompare(b))) {
    // [label, type, min, max, default, unit]
    params[key] = [p.label ?? key, TYPE[p.type] ?? p.type, p.min, p.max, p.default, p.unit ?? ""];
  }
  models[id] = {
    n: m.name,
    b: m.based_on ?? "",
    c: m.category,
    sc: m.subcategory ?? "",
    s: m.stereo ? 1 : 0,
    d: [m.dsp?.mono ?? 0, m.dsp?.stereo ?? 0],
    p: params,
  };
}

const out = {
  source: `${catalog.source ?? "HX Edit"} via retr0h/toneharness (MIT)`,
  models,
};
const here = dirname(fileURLToPath(import.meta.url));
const target = join(here, "..", "src", "data", "hx-catalog.gen.ts");
writeFileSync(
  target,
  `// Generated by scripts/build-hx-catalog.mjs. Do not edit by hand.\n` +
    `// Model and parameter data from HX Edit's catalog via retr0h/toneharness (MIT). See src/data/HX_CATALOG_NOTICE.md.\n` +
    `/* eslint-disable */\n` +
    `export const HX_CATALOG_JSON = ${JSON.stringify(JSON.stringify(out))};\n`,
);
console.log(`wrote ${Object.keys(models).length} models to ${target}`);
